// Umbrella header of the ZephyrSystem module.
//
// It exposes the Zephyr C APIs to Swift, and declares the C functions that
// ZephyrSystem implements in Swift with `@c @implementation`
// (see zephyr-sys/src). It is the umbrella header of the ZephyrSystem Clang
// module (module.modulemap), which Swift code imports with `import
// ZephyrSystem`.

#pragma once

// ===== Project Configuration =====

// Include auto-generated configuration header
// This file is generated by Kconfig during the build process and contains
// all the project configuration settings from prj.conf
#include <autoconf.h>

// Standard C library headers
#include <errno.h>
#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>

// ===== Zephyr Kernel APIs =====

// Core kernel functionality including scheduling, threading, and
// synchronization
#include <zephyr/kernel.h>
#include <zephyr/random/random.h>
#include <zephyr/sys/atomic.h>

// Logging: the LOG_LEVEL_* constants and z_log_msg_static_create(). `log.h` is
// safe to include without `CONFIG_LOG`.
#include <zephyr/logging/log.h>

// ===== Device and Hardware APIs =====

#include <zephyr/device.h>  // Generic device model interfaces for hardware access
#include <zephyr/drivers/gpio.h>  // GPIO interfaces for pin control and interrupts

// ===== Filesystem =====

#if defined(CONFIG_FILE_SYSTEM)
#include <zephyr/fs/fs.h>
#endif

// ===== Checksums =====

#if defined(CONFIG_CRC)
#include <zephyr/sys/crc.h>
#endif

// ===== Zephyr Core Imports =====

#include "bounds.h"  // NOLINT(build/include_subdir)
#include "log.h"     // NOLINT(build/include_subdir)
#include "sys.h"     // NOLINT(build/include_subdir)
